import React from 'react';
import styled from '@emotion/styled';
import { MessageSquare, TrendingUp } from 'lucide-react';
import { theme } from '@atlantis/shared';
import { useFetch, getDomain } from '../hooks';
import { SectionHeader } from './SectionHeader';

const ACCENT = '#d29922';

interface HNStory {
  objectID: string;
  title: string;
  url: string | null;
  points: number;
  num_comments: number;
}

interface HNResponse {
  hits: HNStory[];
}

const List = styled.ol`
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 2px;
`;

const Item = styled.li``;

const ItemLink = styled.a`
  display: flex;
  align-items: flex-start;
  gap: ${theme.spacing.sm};
  padding: 8px ${theme.spacing.sm};
  border-radius: ${theme.borderRadius.sm};
  text-decoration: none;
  transition: background 0.12s;

  &:hover {
    background: ${theme.colors.sidebarHover};
  }
`;

const Rank = styled.span`
  font-size: ${theme.typography.fontSizeSm};
  font-weight: 700;
  color: ${theme.colors.mainTextMuted};
  font-family: ${theme.typography.fontFamilyMono};
  min-width: 20px;
  text-align: right;
  flex-shrink: 0;
  padding-top: 1px;
`;

const Content = styled.div`
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex: 1;
  min-width: 0;
`;

const Title = styled.div`
  font-size: ${theme.typography.fontSizeBase};
  color: ${theme.colors.mainText};
  line-height: 1.4;
`;

const Meta = styled.div`
  display: flex;
  align-items: center;
  gap: ${theme.spacing.sm};
  font-size: 12px;
  color: ${theme.colors.mainTextMuted};
  font-family: ${theme.typography.fontFamilyMono};
`;

const Score = styled.span`
  display: flex;
  align-items: center;
  gap: 3px;
  color: ${ACCENT};
  font-weight: 600;
`;

const Comments = styled.span`
  display: flex;
  align-items: center;
  gap: 3px;
`;

const Domain = styled.span`
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
`;

const EmptyState = styled.div`
  padding: ${theme.spacing.xl};
  color: ${theme.colors.mainTextMuted};
  font-size: ${theme.typography.fontSizeSm};
  text-align: center;
`;

export default function TodayInTech() {
  const url = 'https://hn.algolia.com/api/v1/search?tags=front_page&hitsPerPage=12';
  const { data, loading, lastUpdated, refresh } = useFetch<HNResponse>(url);

  const stories = data?.hits ?? [];

  return (
    <div>
      <SectionHeader
        title="Today in Tech"
        color={ACCENT}
        lastUpdated={lastUpdated}
        loading={loading}
        onRefresh={refresh}
      />
      {!stories.length ? (
        <EmptyState>{loading ? 'Loading front page…' : 'No stories available'}</EmptyState>
      ) : (
        <List>
          {stories.map((story, i) => {
            const href = story.url ?? `https://news.ycombinator.com/item?id=${story.objectID}`;
            return (
              <Item key={story.objectID}>
                <ItemLink href={href} target="_blank" rel="noopener noreferrer">
                  <Rank>{i + 1}.</Rank>
                  <Content>
                    <Title>{story.title}</Title>
                    <Meta>
                      <Score><TrendingUp size={11} />{story.points ?? 0}</Score>
                      <Comments><MessageSquare size={11} />{story.num_comments ?? 0}</Comments>
                      <Domain>{getDomain(story.url)}</Domain>
                    </Meta>
                  </Content>
                </ItemLink>
              </Item>
            );
          })}
        </List>
      )}
    </div>
  );
}
